pub fn onExitPrize<'a>(ctx: &'a Ctx, state: GameModeState<'a>) {
    let __frame = ctx.stack_frame(0x8);
    let mut state = state;
    fns::gm_SetPendingGameMode(ctx, (fns::gm_GetChallengerData(ctx)).curr_mode());
    fns::gm_SetNewGameModePending(ctx);
}

fn inl_lbCardGame_SetupArchive_unfused<'a>(ctx: &'a Ctx) {
    fns::lbCardNew_AllocWorkArea(ctx);
    fns::lbCardGame_LoadArchive(ctx, 0_i32);
    fns::lbCardGame_SaveChanges(ctx);
}

